//////////////////////////////////////////////
// 1) Helper function to compute Mandelbrot
//////////////////////////////////////////////
int mandelbrotIterations(in vec2 c) 
{
    const int MAX_ITER = 100;
    vec2 z = vec2(0.0);
    for(int i = 0; i < MAX_ITER; i++)
    {
        if(dot(z, z) > 4.0)
        {
            return i; // Escaped
        }
        // z = z^2 + c
        z = vec2(z.x*z.x - z.y*z.y + c.x, 
                 2.0*z.x*z.y + c.y);
    }
    return MAX_ITER; // In the set
}

//////////////////////////////////////////////
// 2) The mainImage function
//////////////////////////////////////////////
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    //---------------------------------------
    // Coordinate Setup
    //---------------------------------------
    // Convert fragCoord from [0, iResolution.xy] into a
    // coordinate system of [-1, 1], preserving aspect ratio.
    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    //---------------------------------------
    // Swirl
    //---------------------------------------
    float r     = length(uv);
    float angle = atan(uv.y, uv.x);

    // Reduce swirl amplitude to avoid losing the fractal
    // e.g., from 0.3 down to 0.15
    angle += sin(r * 5.0 - iTime * 2.0) * 0.6;

    // Rebuild cartesian coords from swirl
    uv = r * vec2(cos(angle), sin(angle));

    //---------------------------------------
    // Background Swirl Color
    //---------------------------------------
    vec3 swirlColor = 0.5 + 0.5 * cos(
        iTime * 2.0 + vec3(0.0, 2.0, 4.0)
        + vec3(uv.x, uv.y, uv.x + uv.y)
    );

    //---------------------------------------
    // Mandelbrot with Gentler Zoom
    //---------------------------------------
    // We'll let zoomFactor oscillate between 1.0 and 3.0 over time.
    float zoomFactor = 2.0 + sin(iTime * 0.5); 
    // => Range ~ [1.0, 3.0]

    // Shift the coordinates for a “classic” Mandelbrot region
    // The center is near (-0.75, 0), but let's add a slight horizontal sway.
    vec2 center = vec2(-0.75 + 0.2 * cos(iTime * 0.3), 0.0);

    // Apply zoom and offset
    vec2 mandelUV = uv * zoomFactor + center;

    //---------------------------------------
    // Calculate Mandelbrot
    //---------------------------------------
    int itCount = mandelbrotIterations(mandelUV);
    float t = float(itCount) / 100.0; // Normalized iteration in [0,1]

    //---------------------------------------
    // Mandelbrot Coloring
    //---------------------------------------
    // If it hits MAX_ITER, we consider it "inside" => black
    // Otherwise, use a simple “rainbow” palette
    vec3 mandelColor = (itCount >= 100)
        ? vec3(0.0)
        : 0.5 + 0.5 * cos(6.2831 * (3.0 * t + vec3(0.0, 0.33, 0.67)));

    //---------------------------------------
    // Blend
    //---------------------------------------
    // Mix half swirl, half Mandelbrot
    vec3 finalColor = mix(swirlColor, mandelColor, 0.5);
    fragColor = vec4(finalColor, 1.0);
}
